window.AUTH=window.AUTH||{};window.AUTH["20-297"]={"d":"20-297","id":"2020/20-297","n":"TransUnion LLC v. Ramirez","briefs":[{"k":"petitioner","label":"Brief of petitioner TransUnion LLC","date":"2021-02-01","url":"https://www.supremecourt.gov/DocketPDF/20/20-297/167775/20210201120011675_2021-02-01%20TU%20merits%20opening%20brief%20Final.pdf","side":"pet","n":48},{"k":"united-states","label":"Brief amicus curiae of the United States in support of neither party","date":"2021-02-08","url":"https://www.supremecourt.gov/DocketPDF/20/20-297/168481/20210208174216465_20-297%20TransUnion%20v.f.pdf","side":"us","n":62},{"k":"respondent","label":"Brief of respondent Sergio L. Ramirez","date":"2021-03-03","url":"https://www.supremecourt.gov/DocketPDF/20/20-297/170894/20210304111351491_20-297BriefForRespondent.pdf","side":"res","n":58},{"k":"reply","label":"Reply of petitioner TransUnion LLC","date":"2021-03-19","url":"https://www.supremecourt.gov/DocketPDF/20/20-297/172410/20210319123536081_20-297%20TransUnion%20merits%20reply%20brief%20Final.pdf","side":"pet","n":16}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/594us2r59_197d.pdf","tr":true,"items":[{"t":"case","label":"AmChem Prods. v. Windsor","cite":"521 U.S. 591","y":1997,"id":"1996/96-270","sc":1,"op":2,"sum":"In resolving the case the Court declined to reach the issue of whether the settlement proceeding was a justiciable case or controversy under Article III because, it held, determination of class certification was logically antecedent to these issues.","sumSrc":"Oyez","by":{"0":"28, 34"}},{"t":"case","label":"Barr v. Am. Ass’n of Pol. Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Broussard v. Meineke Disc. Muffler Shops, Inc.","cite":"155 F.3d 331","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/155/331/","by":{"0":"45","1":"29"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"op":4,"ar":2,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"3, 26, 39","2":"2, 32, 33, 34","3":"13"}},{"t":"case","label":"Comcast Corp. v. Behrend","cite":"569 U.S. 27","y":2013,"id":"2012/11-864","sc":1,"sum":"The Court found that district courts cannot certify a class without adequate admissible evidence that damages may be measured and quantified on a class-wide basis.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Cortez v. Trans Union LLC","cite":"617 F.3d 688","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/617/688/","op":7,"ar":1,"by":{"0":"9, 49","2":"passim","3":"15"}},{"t":"case","label":"Dreher v. Experian Info. Sols., Inc.","cite":"856 F.3d 337","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/856/337/","by":{"0":"33"}},{"t":"case","label":"Elk Grove Unified Sch. Dist. v. Newdow","cite":"542 U.S. 1","y":2004,"id":"2003/02-1624","sc":1,"op":1,"sum":"The Court held that a divorced father did not have sufficient custody of his daughter to challenge the Establishment Clause of the First Amendment on her behalf.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"FEC v. Akins","cite":"524 U.S. 11","y":1998,"id":"1997/96-1590","sc":1,"op":2,"sum":"The Court held that voters seeking information, to which they believe FECA entitles them, have standing to challenge the FEC's decision not to bring an enforcement action. Because FECA seeks to address the voters' injury, the failure to obtain relevant information, Justice Breyer concluded that the voters had prudential standing.","sumSrc":"Oyez","by":{"0":"30","1":"21, 22, 23"}},{"t":"case","label":"Flecha v. Medicredit, Inc.","cite":"946 F.3d 762","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/946/762/","by":{"0":"31"}},{"t":"case","label":"Frank v. Gaos","cite":"139 S. Ct. 1041","y":2019,"id":"2018/17-961","sc":1,"sum":"This class action settlement case is remanded for the courts below to address the plaintiffs’ standing in light of Spokeo, Inc. v. Robins, 578 U. S. ___.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"6","1":"2","2":"37, 40","3":"14"}},{"t":"case","label":"Gillespie v. Equifax Info. Servs., L.L.C.","cite":"484 F.3d 938","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/484/938/","by":{"0":"5, 32"}},{"t":"case","label":"Groshek v. Time Warner Cable, Inc.","cite":"865 F.3d 884","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/865/884/","by":{"0":"31, 33"}},{"t":"case","label":"Hansberry v. Lee","cite":"311 U.S. 32","y":1940,"id":"scdb/1940-006","sc":1,"sum":"Numerous owners of lots in a particular area agreed in writing, each severally with each of the others, that their lots should not be sold to or occupied by Negroes, the effectiveness of the agreement being conditioned, however, upon signing by owners of a specified percentage of the lot frontage. In a case in a state court, tried upon an agreed statement of facts, in which it was stipulated (erroneously) that this …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Havens Realty Corp. v. Coleman","cite":"455 U.S. 363","y":1982,"id":"1981/80-988","sc":1,"op":2,"ar":3,"sum":"Section 804 of the Fair Housing Act of 1968 (Act) makes unlawful various forms of discriminatory housing practices. Section 812(a) authorizes civil actions to enforce §804 and requires that suit be brought within 180 days after the alleged occurrence of a discriminatory practice. A class action for declaratory, injunctive, and monetary relief was brought in Federal District Court against petitioners-Havens Realty …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"ar":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"25","2":"34-35, 41"}},{"t":"case","label":"Lujan v. Defs. of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":15,"ar":3,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"6, 7, 25","1":"11","3":"16"}},{"t":"case","label":"Milkovich v. Lorain Journal Co.","cite":"497 U.S. 1","y":1990,"id":"1989/89-645","sc":1,"op":1,"sum":"The Supreme Court held that there is no special constitutional privilege for opinions. The statements in the newspaper were sufficiently factual to be proved true or false. Justice William J. Brennan wrote a dissent, expressing that the statements could not reasonably be interpreted as defamatory. Justice Thurgood Marshall joined in the dissent.","sumSrc":"Oyez","by":{"0":"42","2":"25"}},{"t":"case","label":"O’Shea v. Littleton","cite":"414 U.S. 488","y":1974,"id":"1973/72-953","sc":1,"sum":"Respondents, 17 black and two white residents of Cairo, Illinois, brought a civil rights class action against petitioners, a magistrate and a circuit court jfidge, who allegedly engaged under'color of state law, in a continuing pattern and practice of conduct consisting of illegal bond-setting, sentencing, and jury-fee practices in criminal cases, which assertedly deprived respondents and members of their class of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Ortiz v. Fibreboard Corp.","cite":"527 U.S. 815","y":1999,"id":"1998/97-1704","sc":1,"sum":"The Court held that \"applicants for contested certification [of a mandatory settlement class on a limited fund theory under Rule 23(b)(1)(B)] must show that the fund is limited by more than the agreement of the parties, and has been allocated to claimants belonging within the class by a process addressing any conflicting interests of class members.\" \"The record on which the District Court rested its certification of the class for the purpose of the global settlement did not support the essential premises of mandatory limited fund actions.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Owner-Operator Indep. Drivers. Ass’n v. Dep’t of Transp.","cite":"879 F.3d 339","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/879/339/","op":4,"by":{"0":"38","2":"28"}},{"t":"case","label":"Pub. Citizen v. Dep’t of Just.","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"op":4,"ar":2,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"10, 21, 22, 23"}},{"t":"case","label":"Robins v. Spokeo, Inc.","cite":"742 F.3d 409","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/742/409/","by":{"0":"6","1":"13"}},{"t":"case","label":"Safeco Ins. Co. of Am. v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"sum":"The Court ruled that insurance companies can be liable for willful violations of the Fair Credit Reporting Act if they show \"reckless disregard\" for the law. The justices held that the meaning of the term \"willful\" is contextually determined.","sumSrc":"Oyez","by":{"0":"4","1":"3, 4","2":"19"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"136 S. Ct. 1540","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"14"}},{"t":"case","label":"Sprint Commc’ns Co., L.P. v. APCC Servs., Inc.","cite":"554 U.S. 269","y":2008,"id":"2007/07-552","sc":1,"op":2,"sum":"In a close 5-4 ruling, the Court held that third-party companies like APCC have standing to pursue legal claims that have been assigned to them, even when they must then pass along any proceeds from the litigation to the pay-phone operators who hired them.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Steel Co. v. Citizens for Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":2,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"25","2":"41-42"}},{"t":"case","label":"Summers v. Earth Island Inst.","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"op":5,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"0":"26","1":"13"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"op":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Town of Chester v. Laroe Ests., Inc.","cite":"137 S. Ct. 1645","y":2017,"id":"2016/16-605","sc":1,"sum":"The Court determined that an intervenor to a lawsuit must meet the requirements of Article III standing if the intervenor wishes to pursue relief that was not already requested by the plaintiff.","sumSrc":"Oyez","by":{"0":"27, 34, 43","1":"11","3":"3"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Dukes","cite":"564 U.S. 338","y":2011,"id":"2010/10-277","sc":1,"ar":1,"sum":"The Court held that the small group who initiated a lawsuit could not represent all of Wal-Mart's female employees, and therefore could not bring a class action lawsuit against Wal-Mart.","sumSrc":"Oyez","by":{"0":"34, 43, 44, 48","1":"27","2":"43","3":"17, 18"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"op":5,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"13","3":"14"}},{"t":"case","label":"Whitmore v. Arkansas","cite":"495 U.S. 149","y":1990,"id":"1989/88-7146","sc":1,"op":1,"sum":"Whitmore lacks standing to proceed in this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"usc","label":"15 U.S.C. § 1681a","url":"https://www.law.cornell.edu/uscode/text/15/1681a","subs":["(d)","(f)","(g)","(b)","(d)(1)"],"stext":{"head":"§1681a. Definitions; rules of construction","paras":[[0,"(a) Definitions and rules of construction set forth in this section are applicable for the purposes of this subchapter."],[0,"(b) The term \"person\" means any individual, partnership, corporation, trust, estate, cooperative, association, government or governmental subdivision or agency, or other entity."],[0,"(c) The term \"consumer\" means an individual."],[0,"(d) Consumer Report.—"],[1,"(1) In general.—The term \"consumer report\" means any written, oral, or other communication of any information by a consumer reporting agency bearing on a consumer's credit worthiness, credit standing, credit capacity, character, general reputation, personal characteristics, or mode of living which is used or expected to be used or collected in whole or in part for the purpose of serving as a factor in establishing the consumer's eligibility for—"],[2,"(A) credit or insurance to be used primarily for personal, family, or household purposes;"],[2,"(B) employment purposes; or"],[2,"(C) any other purpose authorized under section 1681b of this title."],[1,"(2) Exclusions.—Except as provided in paragraph (3), the term \"consumer report\" does not include—"],[2,"(A) subject to section 1681s–3 of this title, any—"],[3,"(i) report containing information solely as to transactions or experiences between the consumer and the person making the report;"],[3,"(ii) communication of that information among persons related by common ownership or affiliated by corporate control; or"],[3,"(iii) communication of other information among persons related by common ownership or affiliated by corporate control, if it is clearly and conspicuously disclosed to the consumer that the information may be communicated among such persons and the consumer is given the opportunity, before the time that the information is initially communicated, to direct that such information not be communicated among such persons;"],[2,"(B) any authorization or approval of a specific extension of credit directly or indirectly by the issuer of a credit card or similar device;"],[2,"(C) any report in which a person who has been requested by a third party to make a specific extension of credit directly or indirectly to a consumer conveys his or her decision with respect to such request, if the third party advises the consumer of the name and address of the person to whom the request was made, and such person makes the disclosures to the consumer required under section 1681m of this title; or"],[2,"(D) a communication described in subsection (o) or (x).1"],[1,"(3) Restriction on sharing of medical information.—Except for information or any communication of information disclosed as provided in section 1681b(g)(3) of this title, the exclusions in paragraph (2) shall not apply with respect to information disclosed to any person related by common ownership or affiliated by corporate control, if the information is—"],[2,"(A) medical information;"],[2,"(B) an individualized list or description based on the payment transactions of the consumer for medical products or services; or"],[2,"(C) an aggregate list of identified consumers based on payment transactions for medical products or services."],[0,"(e) The term \"investigative consumer report\" means a consumer report or portion thereof in which information on a consumer's character, general reputation, personal characteristics, or mode of living is obtained through personal interviews with neighbors, friends, or associates of the consumer reported on or with others with whom he is acquainted or who may have knowledge concerning any such items of information. However, such information shall not include specific factual information on a consumer's credit record obtained directly from a creditor of the consumer or from a consumer reporting agency when such information was obtained directly from a creditor of the consumer or from the consumer."],[0,"(f) The term \"consumer reporting agency\" means any person which, for monetary fees, dues, or on a cooperative nonprofit basis, regularly engages in whole or in part in the practice of assembling or evaluating consumer credit information or other information on consumers for the purpose of furnishing consumer reports to third parties, and which uses any means or facility of interstate commerce for the purpose of preparing or furnishing consumer reports."],[0,"(g) The term \"file\", when used in connection with information on any consumer, means all of the information on that consumer recorded and retained by a consumer reporting agency regardless of how the information is stored."],[0,"(h) The term \"employment purposes\" when used in connection with a consumer report means a report used for the purpose of evaluating a consumer for employment, promotion, reassignment or retention as an employee."],[0,"(i) Medical Information.—The term \"medical information\"—"],[1,"(1) means information or data, whether oral or recorded, in any form or medium, created by or derived from a health care provider or the consumer, that relates to—"],[2,"(A) the past, present, or future physical, mental, or behavioral health or condition of an individual;"],[2,"(B) the provision of health care to an individual; or"],[2,"(C) the payment for the provision of health care to an individual.2"],[1,"(2) does not include the age or gender of a consumer, demographic information about the consumer, including a consumer's residence address or e-mail address, or any other information about a consumer that does not relate to the physical, mental, or behavioral health or condition of a consumer, including the existence or value of any insurance policy."],[0,"(j) Definitions Relating to Child Support Obligations.—"],[1,"(1) Overdue support.—The term \"overdue support\" has the meaning given to such term in section 666(e) of title 42."],[1,"(2) State or local child support enforcement agency.—The term \"State or local child support enforcement agency\" means a State or local agency which administers a State or local program for establishing and enforcing child support obligations."],[0,"(k) Adverse Action.—"],[1,"(1) Actions included.—The term \"adverse action\"—"],[2,"(A) has the same meaning as in section 1691(d)(6) of this title; and"],[2,"(B) means—"],[3,"(i) a denial or cancellation of, an increase in any charge for, or a reduction or other adverse or unfavorable change in the terms of coverage or amount of, any insurance, existing or applied for, in connection with the underwriting of insurance;"],[3,"(ii) a denial of employment or any other decision for employment purposes that adversely affects any current or prospective employee;"],[3,"(iii) a denial or cancellation of, an increase in any charge for, or any other adverse or unfavorable change in the terms of, any license or benefit described in section 1681b(a)(3)(D) of this title; and"],[3,"(iv) an action taken or determination that is—"],[4,"(I) made in connection with an application that was made by, or a transaction that was initiated by, any consumer, or in connection with a review of an account under section 1681b(a)(3)(F)(ii) of this title; and"],[4,"(II) adverse to the interests of the consumer."],[1,"(2) Applicable findings, decisions, commentary, and orders.—For purposes of any determination of whether an action is an adverse action under paragraph (1)(A), all appropriate final findings, decisions, commentary, and orders issued under section 1691(d)(6) of this title by the Bureau or any court shall apply."],[0,"(l) Firm Offer of Credit or Insurance.—The term \"firm offer of credit or insurance\" means any offer of credit or insurance to a consumer that will be honored if the consumer is determined, based on information in a consumer report on the consumer, to meet the specific criteria used to select the consumer for the offer, except that the offer may be further conditioned on one or more of the following:"],[1,"(1) The consumer being determined, based on information in the consumer's application for the credit or insurance, to meet specific criteria bearing on credit worthiness or insurability, as applicable, that are established—"],[2,"(A) before selection of the consumer for the offer; and"],[2,"(B) for the purpose of determining whether to extend credit or insurance pursuant to the offer."],[1,"(2) Verification—"],[2,"(A) that the consumer continues to meet the specific criteria used to select the consumer for the offer, by using information in a consumer report on the consumer, information in the consumer's application for the credit or insurance, or other information bearing on the credit worthiness or insurability of the consumer; or"],[2,"(B) of the information in the consumer's application for the credit or insurance, to determine that the consumer meets the specific criteria bearing on credit worthiness or insurability."],[1,"(3) The consumer furnishing any collateral that is a requirement for the extension of the credit or insurance that was—"],[2,"(A) established before selection of the consumer for the offer of credit or insurance; and"],[2,"(B) disclosed to the consumer in the offer of credit or insurance."],[0,"(m) Credit or Insurance Transaction That Is Not Initiated by the Consumer.—The term \"credit or insurance transaction that is not initiated by the consumer\" does not include the use of a consumer report by a person with which the consumer has an account or insurance policy, for purposes of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681a?type=usc&year=mostrecent&link-type=html"},"head":"§1681a. Definitions; rules of construction","tname":"Commerce and Trade","by":{"0":"4, 5, 37, 4, 5","1":"3, 3, 3"}},{"t":"usc","label":"15 U.S.C. § 1681b","url":"https://www.law.cornell.edu/uscode/text/15/1681b","subs":["(a)(3)","(a)(3)(F)"],"stext":{"head":"§1681b. Permissible purposes of consumer reports","paras":[[0,"(a) In general"],[0,"Subject to subsection (c), any consumer reporting agency may furnish a consumer report under the following circumstances and no other:"],[1,"(1) In response to the order of a court having jurisdiction to issue such an order, a subpoena issued in connection with proceedings before a Federal grand jury, or a subpoena issued in accordance with section 5318 of title 31 or section 3486 of title 18."],[1,"(2) In accordance with the written instructions of the consumer to whom it relates."],[1,"(3) To a person which it has reason to believe—"],[2,"(A) intends to use the information in connection with a credit transaction involving the consumer on whom the information is to be furnished and involving the extension of credit to, or review or collection of an account of, the consumer; or"],[2,"(B) intends to use the information for employment purposes; or"],[2,"(C) intends to use the information in connection with the underwriting of insurance involving the consumer; or"],[2,"(D) intends to use the information in connection with a determination of the consumer's eligibility for a license or other benefit granted by a governmental instrumentality required by law to consider an applicant's financial responsibility or status; or"],[2,"(E) intends to use the information, as a potential investor or servicer, or current insurer, in connection with a valuation of, or an assessment of the credit or prepayment risks associated with, an existing credit obligation; or"],[2,"(F) otherwise has a legitimate business need for the information—"],[3,"(i) in connection with a business transaction that is initiated by the consumer; or"],[3,"(ii) to review an account to determine whether the consumer continues to meet the terms of the account."],[2,"(G) executive departments and agencies in connection with the issuance of government-sponsored individually-billed travel charge cards."],[1,"(4) In response to a request by the head of a State or local child support enforcement agency (or a State or local government official authorized by the head of such an agency), if the person making the request certifies to the consumer reporting agency that—"],[2,"(A) the consumer report is needed for the purpose of establishing an individual's capacity to make child support payments, determining the appropriate level of such payments, or enforcing a child support order, award, agreement, or judgment;"],[2,"(B) the parentage of the consumer for the child to which the obligation relates has been established or acknowledged by the consumer in accordance with State laws under which the obligation arises (if required by those laws); and"],[2,"(C) the consumer report will be kept confidential, will be used solely for a purpose described in subparagraph (A), and will not be used in connection with any other civil, administrative, or criminal proceeding, or for any other purpose."],[1,"(5) To an agency administering a State plan under section 654 of title 42 for use to set an initial or modified child support award."],[1,"(6) To the Federal Deposit Insurance Corporation or the National Credit Union Administration as part of its preparation for its appointment or as part of its exercise of powers, as conservator, receiver, or liquidating agent for an insured depository institution or insured credit union under the Federal Deposit Insurance Act [12 U.S.C. 1811 et seq.] or the Federal Credit Union Act [12 U.S.C. 1751 et seq.], or other applicable Federal or State law, or in connection with the resolution or liquidation of a failed or failing insured depository institution or insured credit union, as applicable."],[0,"(b) Conditions for furnishing and using consumer reports for employment purposes"],[0,"(1) Certification from user"],[1,"A consumer reporting agency may furnish a consumer report for employment purposes only if—"],[2,"(A) the person who obtains such report from the agency certifies to the agency that—"],[3,"(i) the person has complied with paragraph (2) with respect to the consumer report, and the person will comply with paragraph (3) with respect to the consumer report if paragraph (3) becomes applicable; and"],[3,"(ii) information from the consumer report will not be used in violation of any applicable Federal or State equal employment opportunity law or regulation; and"],[2,"(B) the consumer reporting agency provides with the report, or has previously provided, a summary of the consumer's rights under this subchapter, as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(2) Disclosure to consumer"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), a person may not procure a consumer report, or cause a consumer report to be procured, for employment purposes with respect to any consumer, unless—"],[3,"(i) a clear and conspicuous disclosure has been made in writing to the consumer at any time before the report is procured or caused to be procured, in a document that consists solely of the disclosure, that a consumer report may be obtained for employment purposes; and"],[3,"(ii) the consumer has authorized in writing (which authorization may be made on the document referred to in clause (i)) the procurement of the report by that person."],[0,"(B) Application by mail, telephone, computer, or other similar means"],[2,"If a consumer described in subparagraph (C) applies for employment by mail, telephone, computer, or other similar means, at any time before a consumer report is procured or caused to be procured in connection with that application—"],[3,"(i) the person who procures the consumer report on the consumer for employment purposes shall provide to the consumer, by oral, written, or electronic means, notice that a consumer report may be obtained for employment purposes, and a summary of the consumer's rights under section 1681m(a)(3) 1 of this title; and"],[3,"(ii) the consumer shall have consented, orally, in writing, or electronically to the procurement of the report by that person."],[0,"(C) Scope"],[2,"Subparagraph (B) shall apply to a person procuring a consumer report on a consumer in connection with the consumer's application for employment only if—"],[3,"(i) the consumer is applying for a position over which the Secretary of Transportation has the power to establish qualifications and maximum hours of service pursuant to the provisions of section 31502 of title 49, or a position subject to safety regulation by a State transportation agency; and"],[3,"(ii) as of the time at which the person procures the report or causes the report to be procured the only interaction between the consumer and the person in connection with that employment application has been by mail, telephone, computer, or other similar means."],[0,"(3) Conditions on use for adverse actions"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), in using a consumer report for employment purposes, before taking any adverse action based in whole or in part on the report, the person intending to take such adverse action shall provide to the consumer to whom the report relates—"],[3,"(i) a copy of the report; and"],[3,"(ii) a description in writing of the rights of the consumer under this subchapter, as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(B) Application by mail, telephone, computer, or other similar means"],[2,"(i) If a consumer described in subparagraph (C) applies for employment by mail, telephone, computer, or other similar means, and if a person who has procured a consumer report on the consumer for employment purposes takes adverse action on the employment application based in whole or in part on the report, then the person must provide to the consumer to whom the report relates, in lieu of the notices required under subparagraph (A) of this section and under section 1681m(a) of this title, within 3 business days of taking such action, an oral, written or electronic notification—"],[3,"(I) that adverse action has been taken based in whole or in part on a consumer report received from a consumer reporting agency;"],[3,"(II) of the name, address and telephone number of the consumer reporting agency that furnished the consumer report (including a toll-free telephone number established by the agency if the agency compiles and maintains files on consumers on a nationwide basis);"],[3,"(III) that the consumer reporting agency did not make the decision to take the adverse action and is unable to provide to the consumer the specific reasons why the adverse action was taken; and"],[3,"(IV) that the consumer may, upon providing proper identification, request a free copy of a report and may dispute with the consumer reporting agency the accuracy or completeness of any information in a report."],[2,"(ii) If, under clause (B)(i)(IV), the consumer requests a copy of a consumer report from the person who procured the report, then, within 3 business days of receiving the consumer's request, together with proper identification, the person must send or provide to the consumer a copy of a report and a copy of the consumer's rights as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(C) Scope"],[2,"Subparagraph (B) shall apply to a person procuring a consumer report on a consumer in connection with the consumer's application for employment only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681b?type=usc&year=mostrecent&link-type=html"},"head":"§1681b. Permissible purposes of consumer reports","tname":"Commerce and Trade","by":{"0":"37","1":"3, 20, 20"}},{"t":"usc","label":"15 U.S.C. § 1681d-1681h","url":"https://www.law.cornell.edu/uscode/text/15/1681d-1681h","by":{"0":"37"}},{"t":"usc","label":"15 U.S.C. § 1681e","url":"https://www.law.cornell.edu/uscode/text/15/1681e","subs":["(b)"],"stext":{"head":"§1681e. Compliance procedures","paras":[[0,"(a) Identity and purposes of credit users"],[0,"Every consumer reporting agency shall maintain reasonable procedures designed to avoid violations of section 1681c of this title and to limit the furnishing of consumer reports to the purposes listed under section 1681b of this title. These procedures shall require that prospective users of the information identify themselves, certify the purposes for which the information is sought, and certify that the information will be used for no other purpose. Every consumer reporting agency shall make a reasonable effort to verify the identity of a new prospective user and the uses certified by such prospective user prior to furnishing such user a consumer report. No consumer reporting agency may furnish a consumer report to any person if it has reasonable grounds for believing that the consumer report will not be used for a purpose listed in section 1681b of this title."],[0,"(b) Accuracy of report"],[0,"Whenever a consumer reporting agency prepares a consumer report it shall follow reasonable procedures to assure maximum possible accuracy of the information concerning the individual about whom the report relates."],[0,"(c) Disclosure of consumer reports by users allowed"],[0,"A consumer reporting agency may not prohibit a user of a consumer report furnished by the agency on a consumer from disclosing the contents of the report to the consumer, if adverse action against the consumer has been taken by the user based in whole or in part on the report."],[0,"(d) Notice to users and furnishers of information"],[0,"(1) Notice requirement"],[1,"A consumer reporting agency shall provide to any person—"],[2,"(A) who regularly and in the ordinary course of business furnishes information to the agency with respect to any consumer; or"],[2,"(B) to whom a consumer report is provided by the agency;"],[1,"a notice of such person's responsibilities under this subchapter."],[0,"(2) Content of notice"],[1,"The Bureau shall prescribe the content of notices under paragraph (1), and a consumer reporting agency shall be in compliance with this subsection if it provides a notice under paragraph (1) that is substantially similar to the Bureau prescription under this paragraph."],[0,"(e) Procurement of consumer report for resale"],[0,"(1) Disclosure"],[1,"A person may not procure a consumer report for purposes of reselling the report (or any information in the report) unless the person discloses to the consumer reporting agency that originally furnishes the report—"],[2,"(A) the identity of the end-user of the report (or information); and"],[2,"(B) each permissible purpose under section 1681b of this title for which the report is furnished to the end-user of the report (or information)."],[0,"(2) Responsibilities of procurers for resale"],[1,"A person who procures a consumer report for purposes of reselling the report (or any information in the report) shall—"],[2,"(A) establish and comply with reasonable procedures designed to ensure that the report (or information) is resold by the person only for a purpose for which the report may be furnished under section 1681b of this title, including by requiring that each person to which the report (or information) is resold and that resells or provides the report (or information) to any other person—"],[3,"(i) identifies each end user of the resold report (or information);"],[3,"(ii) certifies each purpose for which the report (or information) will be used; and"],[3,"(iii) certifies that the report (or information) will be used for no other purpose; and"],[2,"(B) before reselling the report, make reasonable efforts to verify the identifications and certifications made under subparagraph (A)."],[0,"(3) Resale of consumer report to a Federal agency or department"],[1,"Notwithstanding paragraph (1) or (2), a person who procures a consumer report for purposes of reselling the report (or any information in the report) shall not disclose the identity of the end-user of the report under paragraph (1) or (2) if—"],[2,"(A) the end user is an agency or department of the United States Government which procures the report from the person for purposes of determining the eligibility of the consumer concerned to receive access or continued access to classified information (as defined in section 1681b(b)(4)(E)(i) 1 of this title); and"],[2,"(B) the agency or department certifies in writing to the person reselling the report that nondisclosure is necessary to protect classified information or the safety of persons employed by or contracting with, or undergoing investigation for work or contracting with the agency or department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681e?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1681e. Compliance procedures","tname":"Commerce and Trade","by":{"0":"4, 13, 37, 41","1":"21"}},{"t":"usc","label":"15 U.S.C. § 1681g","url":"https://www.law.cornell.edu/uscode/text/15/1681g","subs":["(a)","(c)","(a)(1)","(c)(1)","(c)(1)(B)(iii)","(c)(2)","(c)(2)(A)"],"stext":{"head":"§1681g. Disclosures to consumers","paras":[[0,"(a) Information on file; sources; report recipients"],[0,"Every consumer reporting agency shall, upon request, and subject to section 1681h(a)(1) of this title, clearly and accurately disclose to the consumer:"],[0,"(1) All information in the consumer's file at the time of the request, except that—"],[1,"(A) if the consumer to whom the file relates requests that the first 5 digits of the social security number (or similar identification number) of the consumer not be included in the disclosure and the consumer reporting agency has received appropriate proof of the identity of the requester, the consumer reporting agency shall so truncate such number in such disclosure; and"],[1,"(B) nothing in this paragraph shall be construed to require a consumer reporting agency to disclose to a consumer any information concerning credit scores or any other risk scores or predictors relating to the consumer."],[0,"(2) The sources of the information; except that the sources of information acquired solely for use in preparing an investigative consumer report and actually used for no other purpose need not be disclosed: Provided, That in the event an action is brought under this subchapter, such sources shall be available to the plaintiff under appropriate discovery procedures in the court in which the action is brought."],[0,"(3)(A) Identification of each person (including each end-user identified under section 1681e(e)(1) of this title) that procured a consumer report—"],[1,"(i) for employment purposes, during the 2-year period preceding the date on which the request is made; or"],[1,"(ii) for any other purpose, during the 1-year period preceding the date on which the request is made."],[0,"(B) An identification of a person under subparagraph (A) shall include—"],[1,"(i) the name of the person or, if applicable, the trade name (written in full) under which such person conducts business; and"],[1,"(ii) upon request of the consumer, the address and telephone number of the person."],[0,"(C) Subparagraph (A) does not apply if—"],[1,"(i) the end user is an agency or department of the United States Government that procures the report from the person for purposes of determining the eligibility of the consumer to whom the report relates to receive access or continued access to classified information (as defined in section 1681b(b)(4)(E)(i) 1 of this title); and"],[1,"(ii) the head of the agency or department makes a written finding as prescribed under section 1681b(b)(4)(A) of this title."],[0,"(4) The dates, original payees, and amounts of any checks upon which is based any adverse characterization of the consumer, included in the file at the time of the disclosure."],[0,"(5) A record of all inquiries received by the agency during the 1-year period preceding the request that identified the consumer in connection with a credit or insurance transaction that was not initiated by the consumer."],[0,"(6) If the consumer requests the credit file and not the credit score, a statement that the consumer may request and obtain a credit score."],[0,"(b) Exempt information"],[0,"The requirements of subsection (a) respecting the disclosure of sources of information and the recipients of consumer reports do not apply to information received or consumer reports furnished prior to the effective date of this subchapter except to the extent that the matter involved is contained in the files of the consumer reporting agency on that date."],[0,"(c) Summary of rights to obtain and dispute information in consumer reports and to obtain credit scores"],[0,"(1) Commission 2 summary of rights required"],[0,"(A) In general"],[2,"The Commission 2 shall prepare a model summary of the rights of consumers under this subchapter."],[0,"(B) Content of summary"],[2,"The summary of rights prepared under subparagraph (A) shall include a description of—"],[3,"(i) the right of a consumer to obtain a copy of a consumer report under subsection (a) from each consumer reporting agency;"],[3,"(ii) the frequency and circumstances under which a consumer is entitled to receive a consumer report without charge under section 1681j of this title;"],[3,"(iii) the right of a consumer to dispute information in the file of the consumer under section 1681i of this title;"],[3,"(iv) the right of a consumer to obtain a credit score from a consumer reporting agency, and a description of how to obtain a credit score;"],[3,"(v) the method by which a consumer can contact, and obtain a consumer report from, a consumer reporting agency without charge, as provided in the regulations of the Bureau prescribed under section 211(c) 1 of the Fair and Accurate Credit Transactions Act of 2003; and"],[3,"(vi) the method by which a consumer can contact, and obtain a consumer report from, a consumer reporting agency described in section 1681a(w) 1 of this title, as provided in the regulations of the Bureau prescribed under section 1681j(a)(1)(C) of this title."],[0,"(C) Availability of summary of rights"],[2,"The Commission 2 shall—"],[3,"(i) actively publicize the availability of the summary of rights prepared under this paragraph;"],[3,"(ii) conspicuously post on its Internet website the availability of such summary of rights; and"],[3,"(iii) promptly make such summary of rights available to consumers, on request."],[0,"(2) Summary of rights required to be included with agency disclosures"],[1,"A consumer reporting agency shall provide to a consumer, with each written disclosure by the agency to the consumer under this section—"],[2,"(A) the summary of rights prepared by the Bureau under paragraph (1);"],[2,"(B) in the case of a consumer reporting agency described in section 1681a(p) of this title, a toll-free telephone number established by the agency, at which personnel are accessible to consumers during normal business hours;"],[2,"(C) a list of all Federal agencies responsible for enforcing any provision of this subchapter, and the address and any appropriate phone number of each such agency, in a form that will assist the consumer in selecting the appropriate agency;"],[2,"(D) a statement that the consumer may have additional rights under State law, and that the consumer may wish to contact a State or local consumer protection agency or a State attorney general (or the equivalent thereof) to learn of those rights; and"],[2,"(E) a statement that a consumer reporting agency is not required to remove accurate derogatory information from the file of a consumer, unless the information is outdated under section 1681c of this title or cannot be verified."],[0,"(d) Summary of rights of identity theft victims"],[0,"(1) In general"],[1,"The Commission,2 in consultation with the Federal banking agencies and the National Credit Union Administration, shall prepare a model summary of the rights of consumers under this subchapter with respect to the procedures for remedying the effects of fraud or identity theft involving credit, an electronic fund transfer, or an account or transaction at or with a financial institution or other creditor."],[0,"(2) Summary of rights and contact information"],[1,"Beginning 60 days after the date on which the model summary of rights is prescribed in final form by the Bureau pursuant to paragraph (1), if any consumer contacts a consumer reporting agency and expresses a belief that the consumer is a victim of fraud or identity theft involving credit, an electronic fund transfer, or an account or transaction at or with a financial institution or other creditor, the consumer reporting agency shall, in addition to any other action that the agency may take, provide the consumer with a summary of rights that contains all of the information required by the Bureau under paragraph (1), and information on how to contact the Bureau to obtain more detailed information."],[0,"(e) Information available to victims"],[0,"(1) In general"],[1,"For the purpose of documenting fraudulent transactions resulting from identity theft, not later than 30 days after the date of receipt of a request from a victim in accordance with paragraph (3), and subject to verification of the identity of the victim and the claim of identity theft in accordance with paragraph (2), a business entity that has provided credit to, provided for consideration products, goods, or services to, accepted payment from, or otherwise entered into a commercial transaction for consideration with, a person who has allegedly made unauthorized use of the means of identification of the victim, shall provide a copy of application and business transaction records in the control of the business entity, whether maintained by the business entity or by another person on behalf of the business entity, evidencing any transaction alleged to be a result of identity theft to—"],[2,"(A) the victim;"],[2,"(B) any Federal, State, or local government law enforcement agency or officer specified by the victim in such a request; or"],[2,"(C) any law enforcement agency investigating the identity theft and authorized by the victim to take receipt of records provided under this subsection."],[0,"(2) Verification of identity and claim"],[1,"Before a business entity provides any information under paragraph (1), unless the business entity, at its discretion, otherwise has a high degree of confidence that it knows the identity of the victim making a request under paragraph (1), the victim shall provide to the business entity—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681g?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681g. Disclosures to consumers","tname":"Commerce and Trade","by":{"0":"5, 13, 29, 5, 13, 30","1":"21, 21, 21, 21, 21"}},{"t":"usc","label":"15 U.S.C. § 1681n","url":"https://www.law.cornell.edu/uscode/text/15/1681n","subs":["(a)","(a)(1)(A)","(a)(2)"],"stext":{"head":"§1681n. Civil liability for willful noncompliance","paras":[[0,"(a) In general"],[0,"Any person who willfully fails to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1)(A) any actual damages sustained by the consumer as a result of the failure or damages of not less than $100 and not more than $1,000; or"],[1,"(B) in the case of liability of a natural person for obtaining a consumer report under false pretenses or knowingly without a permissible purpose, actual damages sustained by the consumer as a result of the failure or $1,000, whichever is greater;"],[1,"(2) such amount of punitive damages as the court may allow; and"],[1,"(3) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Civil liability for knowing noncompliance"],[0,"Any person who obtains a consumer report from a consumer reporting agency under false pretenses or knowingly without a permissible purpose shall be liable to the consumer reporting agency for actual damages sustained by the consumer reporting agency or $1,000, whichever is greater."],[0,"(c) Attorney's fees"],[0,"Upon a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."],[0,"(d) Clarification of willful noncompliance"],[0,"For the purposes of this section, any person who printed an expiration date on any receipt provided to a consumer cardholder at a point of sale or transaction between December 4, 2004, and June 3, 2008, but otherwise complied with the requirements of section 1681c(g) of this title for such receipt shall not be in willful noncompliance with section 1681c(g) of this title by reason of printing such expiration date on the receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681n?type=usc&year=mostrecent&link-type=html"},"head":"§1681n. Civil liability for willful noncompliance","tname":"Commerce and Trade","by":{"0":"5","1":"21, 21, 21, 21"}},{"t":"usc","label":"15 U.S.C. § 1681o","url":"https://www.law.cornell.edu/uscode/text/15/1681o","subs":["(a)","(a)(1)"],"stext":{"head":"§1681o. Civil liability for negligent noncompliance","paras":[[0,"(a) In general"],[0,"Any person who is negligent in failing to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1) any actual damages sustained by the consumer as a result of the failure; and"],[1,"(2) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Attorney's fees"],[0,"On a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681o?type=usc&year=mostrecent&link-type=html"},"head":"§1681o. Civil liability for negligent noncompliance","tname":"Commerce and Trade","by":{"0":"5","1":"21, 21"}},{"t":"usc","label":"15 U.S.C. § 1681u-1681v","url":"https://www.law.cornell.edu/uscode/text/15/1681u-1681v","by":{"0":"37"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","subs":["(b)"],"stext":{"head":"§2072. Rules of procedure and evidence; power to prescribe","paras":[[0,"(a) The Supreme Court shall have the power to prescribe general rules of practice and procedure and rules of evidence for cases in the United States district courts (including proceedings before magistrate judges thereof) and courts of appeals."],[0,"(b) Such rules shall not abridge, enlarge or modify any substantive right. All laws in conflict with such rules shall be of no further force or effect after such rules have taken effect."],[0,"(c) Such rules may define when a ruling of a district court is final for the purposes of appeal under section 1291 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2072?type=usc&year=mostrecent&link-type=html"},"head":"§2072. Rules of procedure and evidence; power to prescribe","tname":"Judiciary and Judicial Procedure","by":{"0":"28","3":"19"}},{"t":"reg","label":"31 C.F.R. pt. 501","url":"https://www.ecfr.gov/current/title-31/part-501","by":{"0":"9","1":"18","2":"3"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(a)(3)","(c)(1)(A)","(a)"],"by":{"0":"15, 44","2":"passim, 9, 19, 23, 47, 47","3":"18"}},{"t":"rule","label":"Fed. R. Civ. P. 82","url":"https://www.law.cornell.edu/rules/frcp/rule_82","by":{"0":"28"}},{"t":"case","label":"Beaudry v. TeleCheck Servs., Inc.","cite":"579 F.3d 702","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/579/702/","sum":"Describing statutory damages as an “alternative form of relief”.","sumSrc":"brief:2","by":{"1":"30","2":"38-39"}},{"t":"case","label":"Bryant v. Media Right Prods., Inc.","cite":"603 F.3d 135","y":2010,"url":"https://www.courtlistener.com/c/F.3d/603/135/","by":{"1":"31"}},{"t":"case","label":"Department of the Army v. Blue Fox, Inc.","cite":"525 U.S. 255","y":1999,"id":"1998/97-1642","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court ruled that \"unless waived by Congress, sovereign immunity bars subcontractors and other creditors from enforcing liens on government property or funds to recoup their losses.\" The APA prohibits people and companies with grievances from suing the government for monetary damages.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Doe v. Chao","cite":"306 F.3d 170","y":2002,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/306/170/","by":{"1":"29"}},{"t":"case","label":"Electronic Privacy Information Ctr. v. Presidential Advisory Comm’n on Election Integrity","cite":"878 F.3d 371","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/878/371/","by":{"1":"25, 26"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"General Tel. Co. of the Sw. v. Falcon","cite":"457 U.S. 147","y":1982,"id":"1981/81-574","sc":1,"sum":"The District Court erred in permitting respondent to maintain a class action on behalf of both employees who were denied promotion and applicants who were denied employment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27","2":"43"}},{"t":"case","label":"Gertz v. Robert Welch, Inc.","cite":"418 U.S. 323","y":1974,"id":"1973/72-617","sc":1,"op":1,"sum":"Private individuals need only prove negligence to recover in defamation suits against news media","sumSrc":"Oyez","by":{"1":"16","2":"25"}},{"t":"case","label":"Llewellyn v. Allstate Home Loans, Inc.","cite":"711 F.3d 1173","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/711/1173/","sum":"Explaining that a consumer need not prove actual damages to obtain statutory damages under FCRA.","sumSrc":"brief:1","by":{"1":"30"}},{"t":"case","label":"Murray v. GMAC Mortg. Corp.","cite":"434 F.3d 948","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/434/948/","by":{"1":"32"}},{"t":"case","label":"Omega SA v. 375 Canal, LLC","cite":"984 F.3d 244","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/984/244/","by":{"1":"31"}},{"t":"case","label":"Raines v. Byrd","cite":"521 U.S. 811","y":1997,"id":"1996/96-1671","sc":1,"op":3,"sum":"In a 7-to-2 decision, which avoided the question of the Act's constitutionality, the Court held that the individual congressmen lacked proper Article III standing to maintain their suit. The Court explained that the congressmen failed to show how the allegedly unconstitutional Act resulted in their personal injury, since it applied to the entire institution of Congress.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Stearns v. Ticketmaster Corp.","cite":"655 F.3d 1013","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/1013/","sum":"Finding, in a case involving statelaw deceptive-trade-practices claims, that the proposed class representatives were not typical because they were not actually deceived.","sumSrc":"brief:1","by":{"1":"29"}},{"t":"case","label":"Stillmock v. Weis Markets, Inc.","cite":"385 Fed. Appx. 267","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./385/267/","by":{"1":"31, 33"}},{"t":"case","label":"Tyson Foods, Inc. v. Bouaphakeo","cite":"136 S. Ct. 1036","y":2016,"id":"2015/14-1146","sc":1,"op":1,"sum":"The Court determined that a class action is properly certified and maintained, despite differences among the plaintiff class, if all the individual plaintiffs' cases ask the same central question and even if some plaintiffs were not injured and have no legal right to damages.","sumSrc":"Oyez","by":{"1":"2","2":"22, 29","3":"19"}},{"t":"case","label":"Vermont Agency of Nat. Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"passim","2":"passim"}},{"t":"law","label":"Pub. L. No. 94-553","url":"https://www.govinfo.gov/link/statute/90/2541","by":{"1":"31"}},{"t":"usc","label":"17 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/17/504","subs":["(c)(1)"],"by":{"1":"30"}},{"t":"law","label":"Digital Millennium Copyright Act, Pub. L. No. 105-304","url":"https://www.govinfo.gov/link/plaw/105/public/304","by":{"1":"30"}},{"t":"usc","label":"17 U.S.C. § 1203","url":"https://www.law.cornell.edu/uscode/text/17/1203","subs":["(c)(3)"],"by":{"1":"30"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","subs":["(a)","(a)(1)"],"stext":{"head":"§1681. Congressional findings and statement of purpose","paras":[[0,"(a) Accuracy and fairness of credit reporting"],[0,"The Congress makes the following findings:"],[0,"(1) The banking system is dependent upon fair and accurate credit reporting. Inaccurate credit reports directly impair the efficiency of the banking system, and unfair credit reporting methods undermine the public confidence which is essential to the continued functioning of the banking system."],[0,"(2) An elaborate mechanism has been developed for investigating and evaluating the credit worthiness, credit standing, credit capacity, character, and general reputation of consumers."],[0,"(3) Consumer reporting agencies have assumed a vital role in assembling and evaluating consumer credit and other information on consumers."],[0,"(4) There is a need to insure that consumer reporting agencies exercise their grave responsibilities with fairness, impartiality, and a respect for the consumer's right to privacy."],[0,"(b) Reasonable procedures"],[0,"It is the purpose of this subchapter to require that consumer reporting agencies adopt reasonable procedures for meeting the needs of commerce for consumer credit, personnel, insurance, and other information in a manner which is fair and equitable to the consumer, with regard to the confidentiality, accuracy, relevancy, and proper utilization of such information in accordance with the requirements of this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681. Congressional findings and statement of purpose","tname":"Commerce and Trade","by":{"1":"1, 32, 2","2":"passim"}},{"t":"usc","label":"52 U.S.C. § 30101","url":"https://www.law.cornell.edu/uscode/text/52/30101","by":{"1":"22"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","by":{"1":"21"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","by":{"1":"31"}},{"t":"usc","label":"15 U.S.C. § 1117","url":"https://www.law.cornell.edu/uscode/text/15/1117","subs":["(c)(1)"],"by":{"1":"30"}},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","subs":["(g)(4)(A)"],"by":{"1":"12, 12"}},{"t":"usc","label":"47 U.S.C. § 605","url":"https://www.law.cornell.edu/uscode/text/47/605","subs":["(e)(3)(C)(i)(II)"],"by":{"1":"30"}},{"t":"case","label":"ACLU of Ill. v. City of St. Charles","cite":"794 F.2d 265","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/794/265/","by":{"2":"42"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"2":"41, 42"}},{"t":"case","label":"Ashby v. Farmers Ins. Co. of Or.","cite":"592 F. Supp. 2d 1307","y":2008,"court":"D. Or.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/592/1307/","by":{"2":"47"}},{"t":"case","label":"Associated Gen. Contractors of Cal., Inc. v. Cal. State Council of Carpenters","cite":"459 U.S. 519","y":1983,"id":"1982/81-334","sc":1,"sum":"Based on the allegations of the complaint, the Union was not a person injured by reason of a violation of the antitrust laws within the meaning of § 4 of the Clayton Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35"}},{"t":"case","label":"Bacon v. Mich. Cent. R.R. Co.","cite":"21 N.W. 324","y":1884,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./21/324/","by":{"2":"29"}},{"t":"case","label":"Baffa v. Donaldson, Lufkin & Jenrette Secs. Corp.","cite":"222 F.3d 52","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/222/52/","by":{"2":"43"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Berry v. City of N.Y. Ins. Co.","cite":"98 So. 290","y":1923,"court":"Ala.","url":"https://www.courtlistener.com/c/So./98/290/","by":{"2":"28"}},{"t":"case","label":"Biestek v. Berryhill","cite":"139 S. Ct. 1148","y":2019,"id":"2018/17-1184","sc":1,"sum":"A vocational expert’s refusal to provide private market-survey data during a Social Security disability benefits hearing upon the applicant’s request does not categorically preclude the testimony from counting as “substantial evidence” in federal court under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"41"}},{"t":"case","label":"Brownback v. King","cite":"2021 WL 726222","y":2021,"court":"U.S. Feb. 25","ar":1,"by":{"2":"41"}},{"t":"case","label":"Bryant v. Compass Grp. USA, Inc.","cite":"958 F.3d 617","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/958/617/","op":1,"by":{"2":"39"}},{"t":"case","label":"Carey v. Piphus","cite":"435 U.S. 247","y":1978,"id":"1977/76-1149","sc":1,"sum":"The Court held that the purpose of the Civil Rights Act of 1871 is to compensate people for injuries caused by the deprivation of civil rights, which means that compensation cannot occur without proof of injury. However, the definition of injury must be adapted to fit the civil rights in question.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Dart Cherokee Basin Operating Co., LLC v. Owens","cite":"574 U.S. 81","y":2014,"id":"2014/13-719","sc":1,"sum":"The Court ruled that a defendant seeking removal of a case to federal court is not required to provide evidence supporting federal jurisdiction in the notice of removal.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Dimick v. Schiedt","cite":"293 U.S. 474","y":1935,"id":"scdb/1934-155","sc":1,"sum":"1. Under the Seventh Amendment, a federal court, finding a verdict inadequate, is without power to add to it by refusing to grant the plaintiff a new trial if the defendant will accept an increase which the court deems sufficient. So held in an action for personal injuries due to negligence.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"Dreher v. Experian Info. Sols.","cite":"2014 WL 2800766","y":2014,"court":"E.D.V.A. June 19","sum":"Holding that statutory damages awards hinge on defendant’s conduct, and prohibiting class representative from testifying about his “horrible angst” to avoid confusing the jury.","sumSrc":"brief:2","by":{"2":"47"}},{"t":"case","label":"Holmes v. Secs. Investor Prot. Corp.","cite":"503 U.S. 258","y":1992,"id":"1991/90-727","sc":1,"sum":"SIPC has demonstrated no right to sue Holmes under § 1964(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"Huff v. TeleCheck Servs., Inc.","cite":"923 F.3d 458","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/923/458/","op":1,"by":{"2":"39, 41"}},{"t":"case","label":"Kamal v. J. Crew Grp., Inc.","cite":"918 F.3d 102","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/918/102/","by":{"2":"34"}},{"t":"case","label":"Macy v. GC Servs. L.P.","cite":"897 F.3d 747","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/897/747/","by":{"2":"34"}},{"t":"case","label":"Marcus v. BMW of N. Am., LLC","cite":"687 F.3d 583","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/687/583/","sum":"Finding typicality where class representative’s strong facts may have put him “in a better position than other potential class members”.","sumSrc":"brief:2","by":{"2":"43"}},{"t":"case","label":"Memphis Cmty. Sch. Dist. v. Stachura","cite":"477 U.S. 299","y":1986,"id":"1985/85-410","sc":1,"sum":"Damages based on the abstract \"value\" or \"importance\" of constitutional rights are not a permissible element of compensatory damages in § 1983 cases.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"Muransky v. Godiva Chocolatier, Inc.","cite":"979 F.3d 917","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/979/917/","op":2,"by":{"2":"39"}},{"t":"case","label":"Ostrowe v. Lee","cite":"175 N.E. 505","y":1931,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./175/505/","op":1,"by":{"2":"28","3":"6"}},{"t":"case","label":"Postawko v. Mo. Dep’t of Corrs.","cite":"910 F.3d 1030","y":2018,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/910/1030/","by":{"2":"43"}},{"t":"case","label":"Richardson v. Perales","cite":"402 U.S. 389","y":1971,"id":"1970/108","sc":1,"sum":"Written reports by physicians who have examined claimant for disability insurance benefits under Social Security Act constitute \"substantial evidence\" supporting a nondisability finding within the standard of § 205 (g) of the Act, notwithstanding the reports' hearsay character, the absence of cross-examination (through claimant's failure to exercise his subpoena rights), and the directly opposing testimony by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"Robins v. Spokeo, Inc.","cite":"867 F.3d 1108","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1108/","by":{"2":"24, 34"}},{"t":"case","label":"Springer v. Cleveland Clinic Emp. Health Plan Total Care","cite":"900 F.3d 284","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/900/284/","by":{"2":"40"}},{"t":"case","label":"St. Paul Mercury Indem. Co. v. Red Cab Co.","cite":"303 U.S. 283","y":1938,"id":"scdb/1937-104","sc":1,"op":1,"sum":"1. There is a strong presumption that the plaintiff in a state court has not claimed a large amount in order to confer jurisdiction by removal on a federal court, and that the parties have not colluded to that end.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Strubel v. Comenity Bank","cite":"842 F.3d 181","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/842/181/","by":{"2":"32"}},{"t":"case","label":"Tenn. Elec. Power Co. v. TVA","cite":"306 U.S. 118","y":1939,"id":"scdb/1938-131","sc":1,"op":1,"sum":"1. The principle permitting suit against an agent of the Government to restrain execution of an unconstitutional statute protects only legal rights.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Thole v. U.S. Bank N.A.","cite":"140 S. Ct. 1615","y":2020,"id":"2019/17-1712","sc":1,"op":3,"sum":"The Court held that an ERISA plan participant lacks judicial standing to seek injunctive relief or restoration of plan losses caused by fiduciary breach if he cannot demonstrate individual financial loss or the imminent risk thereof.","sumSrc":"Oyez","by":{"2":"34, 39-40"}},{"t":"case","label":"Trichell v. Midland Credit Mgmt., Inc.","cite":"964 F.3d 990","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/964/990/","op":3,"sum":"Noting that Clapper was not applied in Thole v. U.S. Bank N.A., 140 S.Ct. 1615 (2020), involving cause of action under ERISA.","sumSrc":"brief:2","by":{"2":"34"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"const","label":"Article I","by":{"2":"25"}},{"t":"law","label":"Pub. L. No. 107-56","url":"https://www.govinfo.gov/link/plaw/107/public/56","by":{"2":"3"}},{"t":"rule","label":"Fed. R. Civ. P. 16","url":"https://www.law.cornell.edu/rules/frcp/rule_16","by":{"2":"49"}},{"t":"rule","label":"Fed. R. Evid. 403","url":"https://www.law.cornell.edu/rules/fre/rule_403","by":{"2":"47"}},{"t":"case","label":"Chalkley v. Atl. Coast Line R.R. Co.","cite":"143 S.E. 631","y":1928,"court":"Va.","url":"https://www.courtlistener.com/c/S.E./143/631/","op":1,"by":{"3":"6"}},{"t":"case","label":"Curtis Publ’g Co. v. Butts","cite":"388 U.S. 130","y":1967,"id":"1966/37","sc":1,"sum":"The Court held that public figures asserting a defamation claim must show that a statement was made \"with knowledge that it was false or with reckless disregard for whether it was false or not,\" the same standard to which public officials are held under New York Times v. Sullivan.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Mack v. Delta Air Lines, Inc.","cite":"639 F.App’x 582","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.App%E2%80%99x/639/582/","op":1,"by":{"3":"6"}},{"t":"case","label":"Stillmock v. Weis Markets, Inc.","cite":"385 F.App’x 267","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.App%E2%80%99x/385/267/","by":{"3":"20"}}]};